PRAGMA foreign_keys = ON;

-- Initial review queue for the ten niches that previously relied on universal content only.
-- These records intentionally remain in review until their wording is approved in the constructor.
WITH seed (
  id, item_type, speaker, category, title, prompt_text, short_text, full_text,
  clarification_text, next_action_text, channel, tone, required_level, risk_level,
  source_kind, source_url, source_reference, status, version, normalized_key
) AS (
  VALUES
  ('ki-r-children-q1', 'question_to_client', 'creator', 'business', 'Товар, возраст и задача детского бренда', 'Какой именно товар продвигаем, для какого возраста он предназначен и какую задачу должен решить контент?', NULL, NULL, 'Кто выбирает товар: ребёнок, родитель, педагог или организация?', 'Зафиксировать товар, возрастную группу, покупателя и главное действие после просмотра.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: Детские товары', 'review', 1, 'remaining-children-question-1'),
  ('ki-r-children-q2', 'question_to_client', 'creator', 'safety', 'Подтверждённые характеристики детского товара', 'Какие материалы, размеры, возрастные ограничения, сертификаты и правила безопасного использования подтверждены производителем?', NULL, NULL, 'Какие элементы товара и маркировки нельзя изменять в визуале?', 'Составить чек-лист точности и передать финальные материалы на проверку бренду.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Детские товары', 'review', 1, 'remaining-children-question-2'),
  ('ki-r-children-ob1', 'objection_response', 'creator', 'accuracy', 'Ответ: «Можно сделать игрушку ярче и интереснее, чем в жизни»', 'Можно сделать игрушку ярче и интереснее, чем в жизни', 'Атмосферу и окружение можно усилить, но сам товар, его комплектацию, цвет, размер и функции нужно показывать честно. Иначе родитель получит не то, что ожидал по рекламе.', 'Допустима выразительная подача реального товара. Нельзя добавлять функции, детали или комплектацию, которых нет в продаже.', 'Какие характеристики покупатель обязательно должен увидеть без искажений?', 'Согласовать неизменяемые детали и отделить товарный кадр от концептуального.', 'any', 'firm', 'recommended', 'elevated', 'manual', NULL, 'Массовое наполнение: Детские товары', 'review', 1, 'remaining-children-objection-1'),
  ('ki-r-children-ob2', 'objection_response', 'creator', 'privacy', 'Ответ: «Можно создать ребёнка для рекламы без согласий»', 'Можно создать ребёнка для рекламы без согласий', 'Для вымышленного персонажа всё равно нужна безопасная и уважительная подача без сходства с реальным ребёнком. Если используются фотографии или узнаваемая внешность несовершеннолетнего, нужны необходимые согласия и понятные права использования.', 'Нельзя обходить требования к согласию, приватности и достоинству ребёнка с помощью AI.', 'Будут ли использоваться реальные фотографии, имена или узнаваемые черты?', 'Выбрать предметную сцену либо согласованный образ без идентифицирующих данных.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Детские товары', 'review', 1, 'remaining-children-objection-2'),
  ('ki-r-children-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Детские товары', NULL, 'Не показывать опасное использование, не сексуализировать детей, не выдумывать свойства товара и не скрывать возрастные ограничения.', 'Проверить безопасность сцены, точность товара и маркировки, наличие согласий для реальных детей, отсутствие давления на ребёнка и манипуляций страхом родителя.', 'Материал уважает достоинство ребёнка и не создаёт ложного впечатления о безопасности или возможностях товара?', 'Остановить выпуск материала до устранения риска или получения подтверждений.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Детские товары', 'review', 1, 'remaining-children-ethics-1'),

  ('ki-r-tourism-q1', 'question_to_client', 'creator', 'business', 'Объект, сезон и цель туристического контента', 'Какой объект, номер, тур или услугу продвигаем, на какой сезон и какое действие должен совершить гость?', NULL, NULL, 'Нужны прямые бронирования, заявки на даты, знакомство с объектом или продвижение отдельного предложения?', 'Зафиксировать реальный объект, период доступности и путь к бронированию.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: Отели, гостевые дома и туризм', 'review', 1, 'remaining-tourism-question-1'),
  ('ki-r-tourism-q2', 'question_to_client', 'creator', 'accuracy', 'Что гость получит в действительности', 'Какие номера, виды, удобства, питание, трансфер и условия действительно доступны гостю в выбранном тарифе?', NULL, NULL, 'Есть ли сезонные ограничения, ремонт или услуги за отдельную плату?', 'Отделить включённые услуги от дополнительных и проверить соответствие визуалов реальности.', 'any', 'firm', 'required', 'elevated', 'manual', NULL, 'Массовое наполнение: Отели, гостевые дома и туризм', 'review', 1, 'remaining-tourism-question-2'),
  ('ki-r-tourism-ob1', 'objection_response', 'creator', 'accuracy', 'Ответ: «Сделайте номер и вид из окна роскошнее»', 'Сделайте номер и вид из окна роскошнее', 'Можно улучшить свет, композицию и атмосферу, но нельзя увеличивать площадь, менять комплектацию или показывать вид, которого гость не увидит. Концептуальный кадр должен быть явно отделён от демонстрации реального номера.', 'Гость принимает решение по конкретным условиям проживания, поэтому ключевые характеристики должны совпадать с реальностью.', 'Какие реальные преимущества можно подчеркнуть без изменения объекта?', 'Собрать точные исходники и согласовать список допустимых улучшений подачи.', 'any', 'firm', 'recommended', 'high', 'manual', NULL, 'Массовое наполнение: Отели, гостевые дома и туризм', 'review', 1, 'remaining-tourism-objection-1'),
  ('ki-r-tourism-ob2', 'objection_response', 'creator', 'guarantees', 'Ответ: «Контент гарантирует полную загрузку»', 'Контент гарантирует полную загрузку', 'Контент может улучшить понимание предложения и поддержать бронирования, но загрузка зависит от сезона, цены, доступности, отзывов, рекламы, сервиса и скорости ответа. Корректно согласовать метрики, но не обещать полную загрузку.', 'Ответственность за контент отделяется от факторов продаж и операционной работы объекта.', 'Какие показатели сейчас измеряются и где теряются бронирования?', 'Определить проверяемую гипотезу и период оценки без гарантии результата.', 'any', 'firm', 'recommended', 'elevated', 'manual', NULL, 'Массовое наполнение: Отели, гостевые дома и туризм', 'review', 1, 'remaining-tourism-objection-2'),
  ('ki-r-tourism-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Отели и туризм', NULL, 'Не выдумывать инфраструктуру, виды, категорию номера, включённые услуги, расстояния и условия проживания.', 'Концептуальные изображения маркируются. Реальные номера и территория показываются без изменений, способных повлиять на решение гостя.', 'Совпадает ли обещание в материале с тем, что можно забронировать на указанные даты и по указанному тарифу?', 'Исправить материал или явно обозначить концепцию и ограничения.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Отели, гостевые дома и туризм', 'review', 1, 'remaining-tourism-ethics-1'),

  ('ki-r-interior-q1', 'question_to_client', 'creator', 'business', 'Статус интерьерного проекта', 'Что показываем: реализованный интерьер, товар из каталога, проект в работе или концепцию будущего пространства?', NULL, NULL, 'Какое действие должен совершить зритель: заказать проект, выбрать товар или запросить расчёт?', 'Зафиксировать статус проекта и не смешивать реализацию с концепцией.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: Мебель, интерьер и ремонт', 'review', 1, 'remaining-interior-question-1'),
  ('ki-r-interior-q2', 'question_to_client', 'creator', 'accuracy', 'Размеры, материалы и комплектация', 'Какие размеры, материалы, цвета, фактуры и элементы комплектации должны быть переданы без изменений?', NULL, NULL, 'Есть ли чертежи, спецификация и актуальные фотографии образцов?', 'Собрать технические референсы и чек-лист точности до генерации.', 'any', 'firm', 'required', 'elevated', 'manual', NULL, 'Массовое наполнение: Мебель, интерьер и ремонт', 'review', 1, 'remaining-interior-question-2'),
  ('ki-r-interior-ob1', 'objection_response', 'creator', 'transparency', 'Ответ: «Покажем визуализацию как готовый объект»', 'Покажем визуализацию как готовый объект', 'Визуализация помогает представить решение, но её нужно обозначить как проект или концепцию. Выдавать её за фотографию реализованного объекта нельзя: это создаёт ложное портфолио и неверные ожидания.', 'Можно показать проект убедительно, сохранив прозрачную подпись о его статусе.', 'Что уже реализовано и что пока существует только в проекте?', 'Разделить реальные фотографии и визуализации, добавить понятные подписи.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Мебель, интерьер и ремонт', 'review', 1, 'remaining-interior-objection-1'),
  ('ki-r-interior-ob2', 'objection_response', 'creator', 'accuracy', 'Ответ: «Можно изменить планировку, чтобы выглядело просторнее»', 'Можно изменить планировку, чтобы выглядело просторнее', 'Для концепции допустимы варианты планировки, если они технически возможны и обозначены. В материале о конкретном объекте нельзя менять геометрию и масштаб так, чтобы клиент ожидал другое пространство.', 'Свет и ракурс улучшают подачу, но не должны подменять реальные размеры и ограничения.', 'Есть ли подтверждение, что предлагаемая планировка реализуема?', 'Проверить визуал по чертежу и обозначить проектные допущения.', 'any', 'firm', 'recommended', 'high', 'manual', NULL, 'Массовое наполнение: Мебель, интерьер и ремонт', 'review', 1, 'remaining-interior-objection-2'),
  ('ki-r-interior-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Мебель, интерьер и ремонт', NULL, 'Отделять реализованные объекты от визуализаций и точно передавать размеры, материалы, комплектацию и авторство проекта.', 'Не присваивать чужие работы, не скрывать проектный статус и не показывать недоступную комплектацию как включённую.', 'Понятно ли зрителю, что реально выполнено, что продаётся и что является концепцией?', 'Добавить статус, источники и ограничения либо исключить вводящий в заблуждение материал.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Мебель, интерьер и ремонт', 'review', 1, 'remaining-interior-ethics-1'),

  ('ki-r-realestate-q1', 'question_to_client', 'creator', 'business', 'Объект, стадия и доступность недвижимости', 'Какой объект продвигаем, на какой он стадии и какие квартиры, помещения или участки действительно доступны?', NULL, NULL, 'Кто покупатель и какое действие требуется: заявка, звонок, визит или бронирование?', 'Зафиксировать объект, актуальный остаток, стадию и путь обращения.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: Недвижимость и застройщики', 'review', 1, 'remaining-realestate-question-1'),
  ('ki-r-realestate-q2', 'question_to_client', 'creator', 'claims', 'Подтверждённые характеристики объекта', 'Какие сроки, цены, площади, отделка, инфраструктура и условия покупки подтверждены актуальными документами?', NULL, NULL, 'Кто проверяет рекламные формулировки и обновляет сведения при изменении условий?', 'Собрать единую актуальную спецификацию и ответственного за проверку.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Недвижимость и застройщики', 'review', 1, 'remaining-realestate-question-2'),
  ('ki-r-realestate-ob1', 'objection_response', 'creator', 'accuracy', 'Ответ: «Добавьте красивый вид и готовую инфраструктуру»', 'Добавьте красивый вид и готовую инфраструктуру', 'Рендер может показывать планируемый результат, если это явно обозначено и соответствует проекту. Нельзя добавлять несуществующий вид, объекты или благоустройство так, будто они уже доступны покупателю.', 'Визуальная привлекательность не отменяет точность расположения, стадии и заявленных характеристик.', 'Какие элементы утверждены проектом и к какому сроку планируются?', 'Подписать рендер и проверить каждый существенный элемент по актуальным данным.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Недвижимость и застройщики', 'review', 1, 'remaining-realestate-objection-1'),
  ('ki-r-realestate-ob2', 'objection_response', 'creator', 'guarantees', 'Ответ: «Контент гарантирует продажу объекта»', 'Контент гарантирует продажу объекта', 'Контент помогает объяснить преимущества и привести человека к обращению, но решение зависит от цены, документов, локации, спроса, ипотеки и работы отдела продаж. Гарантировать сделку некорректно.', 'Можно согласовать вклад контента и измеримые этапы воронки без обещания продажи.', 'Какая конверсия сейчас измеряется от просмотра до визита и сделки?', 'Выбрать метрики контента и проверить путь обработки обращения.', 'any', 'firm', 'recommended', 'elevated', 'manual', NULL, 'Массовое наполнение: Недвижимость и застройщики', 'review', 1, 'remaining-realestate-objection-2'),
  ('ki-r-realestate-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Недвижимость', NULL, 'Маркировать рендеры, использовать актуальные цены и сроки, не выдумывать инфраструктуру, вид, отделку и юридический статус.', 'Все существенные условия проверяются ответственным представителем клиента перед публикацией. Изменения предложения должны своевременно отражаться в материалах.', 'Может ли покупатель отличить проектное изображение от фотографии и проверить заявленные условия?', 'Остановить публикацию до проверки или добавить ясные ограничения.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Недвижимость и застройщики', 'review', 1, 'remaining-realestate-ethics-1'),

  ('ki-r-womenspaces-q1', 'question_to_client', 'creator', 'business', 'Услуга и границы женского пространства', 'Какую услугу или пространство продвигаем, кому оно предназначено и какой результат клиентка вправе ожидать?', NULL, NULL, 'Это бытовая, эстетическая, образовательная или медицинская услуга?', 'Точно определить категорию услуги и допустимые обещания.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: Женские пространства и допустимые бьюти-услуги', 'review', 1, 'remaining-womenspaces-question-1'),
  ('ki-r-womenspaces-q2', 'question_to_client', 'creator', 'claims', 'Квалификация и подтверждение результата', 'Какие квалификации, санитарные условия, ограничения и результаты услуги подтверждены и могут использоваться в рекламе?', NULL, NULL, 'Есть ли медицинские формулировки или обещания, которые должен проверить специалист?', 'Согласовать список допустимых утверждений и порядок проверки материалов.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Женские пространства и допустимые бьюти-услуги', 'review', 1, 'remaining-womenspaces-question-2'),
  ('ki-r-womenspaces-ob1', 'objection_response', 'creator', 'claims', 'Ответ: «Сделаем идеальное до и после в нейросети»', 'Сделаем идеальное до и после в нейросети', 'AI-изображение нельзя выдавать за доказательство результата процедуры. Для сравнения нужны реальные материалы, необходимые согласия, одинаковые условия съёмки и отсутствие ретуши, меняющей доказательный смысл.', 'Вместо вымышленного результата можно объяснить процесс, атмосферу и подтверждённые преимущества услуги.', 'Есть ли реальные разрешённые материалы и кто подтверждает корректность заявления?', 'Исключить искусственное сравнение или заменить его безопасным форматом.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: Женские пространства и допустимые бьюти-услуги', 'review', 1, 'remaining-womenspaces-objection-1'),
  ('ki-r-womenspaces-ob2', 'objection_response', 'creator', 'ethics', 'Ответ: «Нужен более откровенный образ для внимания»', 'Нужен более откровенный образ для внимания', 'Внимание можно получить через эстетику, детали услуги, пространство и понятный результат без сексуализации женщины. Подача должна сохранять достоинство, приватность и соответствовать ценностям проекта.', 'Отказ от откровенного образа не мешает создать выразительный и коммерчески ясный материал.', 'Как показать ценность услуги через процесс, детали и атмосферу?', 'Предложить скромную предметную или сюжетную концепцию.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Женские пространства и допустимые бьюти-услуги', 'review', 1, 'remaining-womenspaces-objection-2'),
  ('ki-r-womenspaces-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Женские пространства', NULL, 'Сохранять достоинство и приватность женщин, не сексуализировать, не выдумывать результат и не превращать эстетическую услугу в медицинское обещание.', 'Для реальных клиенток нужны согласия и понятные права использования. Чувствительные данные и изображения не публикуются без необходимости.', 'Есть ли согласие, подтверждение результата и безопасная альтернатива демонстрации тела?', 'Удалить чувствительный материал или заменить его уважительной предметной подачей.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Женские пространства и допустимые бьюти-услуги', 'review', 1, 'remaining-womenspaces-ethics-1'),

  ('ki-r-education-q1', 'question_to_client', 'creator', 'business', 'Программа, аудитория и образовательная задача', 'Какую программу или продукт продвигаем, кому он подходит и какое действие должен совершить будущий ученик или родитель?', NULL, NULL, 'Какой уровень подготовки нужен и что входит в программу?', 'Зафиксировать аудиторию, содержание, формат и путь записи.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: Образовательные организации', 'review', 1, 'remaining-education-question-1'),
  ('ki-r-education-q2', 'question_to_client', 'creator', 'claims', 'Подтверждённые образовательные результаты', 'Какие квалификации преподавателей, документы, лицензии и результаты выпускников подтверждены и могут быть указаны?', NULL, NULL, 'Какие условия влияют на результат ученика и должны быть раскрыты?', 'Отделить проверяемые факты от рекламных обещаний.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Образовательные организации', 'review', 1, 'remaining-education-question-2'),
  ('ki-r-education-ob1', 'objection_response', 'creator', 'guarantees', 'Ответ: «Можно гарантировать работу или высокий балл»', 'Можно гарантировать работу или высокий балл', 'Нельзя честно гарантировать результат, который зависит от исходного уровня, усилий ученика, рынка и внешней оценки. Можно точно описать программу, поддержку, критерии завершения и подтверждённые результаты прошлых участников.', 'Обещание заменяется прозрачным описанием процесса и условий успеха.', 'Какие результаты подтверждены и как они измерялись?', 'Сформулировать проверяемое преимущество без гарантии индивидуального исхода.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Образовательные организации', 'review', 1, 'remaining-education-objection-1'),
  ('ki-r-education-ob2', 'objection_response', 'creator', 'trust', 'Ответ: «Создадим отзыв и историю выпускника»', 'Создадим отзыв и историю выпускника', 'Вымышленный отзыв нельзя выдавать за опыт реального ученика. Допустим обезличенный кейс с разрешением и точными данными либо явно обозначенный пример учебной ситуации.', 'Доверие строится на проверяемых историях, а не на созданных свидетельствах.', 'Есть ли согласованный реальный кейс и можно ли подтвердить его детали?', 'Получить разрешение, обезличить данные или отказаться от формата отзыва.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: Образовательные организации', 'review', 1, 'remaining-education-objection-2'),
  ('ki-r-education-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Образование', NULL, 'Не выдумывать отзывы, квалификации, лицензии и гарантированные результаты. Для историй несовершеннолетних получать необходимые согласия.', 'Учебные материалы и цитаты используются с соблюдением авторства. Условия программы и выдаваемые документы описываются точно.', 'Все ли доказательства и разрешения существуют, а ограничения программы понятны до оплаты?', 'Исправить формулировку или исключить неподтверждённый материал.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Образовательные организации', 'review', 1, 'remaining-education-ethics-1'),

  ('ki-r-medical-q1', 'question_to_client', 'creator', 'business', 'Медицинская услуга и ответственный специалист', 'Какую медицинскую услугу продвигаем, кому она показана и кто из специалистов отвечает за проверку информации?', NULL, NULL, 'Какие лицензии, квалификации и ограничения относятся к этой услуге?', 'Назначить медицинского проверяющего и собрать подтверждённые сведения.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Медицинские организации и реабилитационные центры', 'review', 1, 'remaining-medical-question-1'),
  ('ki-r-medical-q2', 'question_to_client', 'creator', 'claims', 'Показания, ограничения и допустимые обещания', 'Какие показания, противопоказания, риски и результаты подтверждены и разрешены для публичной коммуникации?', NULL, NULL, 'Какие формулировки требуют обязательной проверки врачом или юристом клиента?', 'Согласовать факты и исключить обещания лечения без основания.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: Медицинские организации и реабилитационные центры', 'review', 1, 'remaining-medical-question-2'),
  ('ki-r-medical-ob1', 'objection_response', 'creator', 'evidence', 'Ответ: «Сделаем впечатляющее до и после с AI»', 'Сделаем впечатляющее до и после с AI', 'AI-изображение нельзя использовать как доказательство медицинского результата. Реальное сравнение требует согласия пациента, одинаковых условий, корректной подписи и проверки специалистом; ретушь не должна менять клинический смысл.', 'Вместо вымышленного результата можно объяснить этапы помощи, оборудование и подтверждённые принципы работы.', 'Есть ли реальный разрешённый материал и медицинское подтверждение его интерпретации?', 'Отказаться от искусственного результата и выбрать доказуемый формат.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: Медицинские организации и реабилитационные центры', 'review', 1, 'remaining-medical-objection-1'),
  ('ki-r-medical-ob2', 'objection_response', 'creator', 'safety', 'Ответ: «Пусть контент сразу подсказывает диагноз и лечение»', 'Пусть контент сразу подсказывает диагноз и лечение', 'Публичный материал может объяснить услугу и признаки, при которых стоит обратиться к специалисту, но не должен ставить диагноз или назначать лечение конкретному человеку.', 'Индивидуальные медицинские решения принимаются квалифицированным специалистом после надлежащей оценки.', 'Какой безопасный следующий шаг можно предложить без самодиагностики?', 'Заменить назначение лечения приглашением к профессиональной консультации или экстренной помощи при необходимости.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: Медицинские организации и реабилитационные центры', 'review', 1, 'remaining-medical-objection-2'),
  ('ki-r-medical-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Медицинские организации', NULL, 'Не ставить диагноз, не назначать лечение, не обещать гарантированный результат и не раскрывать данные пациента.', 'Все медицинские утверждения, изображения процедур и истории пациентов проверяются ответственным специалистом и используются с необходимыми согласиями.', 'Материал подтверждён, не заменяет консультацию и не раскрывает чувствительные данные?', 'Остановить публикацию до медицинской проверки и устранения риска.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: Медицинские организации и реабилитационные центры', 'review', 1, 'remaining-medical-ethics-1'),

  ('ki-r-health-q1', 'question_to_client', 'creator', 'product', 'Категория и статус товара для здоровья', 'Что это за продукт, каков его официальный статус, состав, назначение и для кого он предназначен?', NULL, NULL, 'Какие документы и маркировка подтверждают допустимое описание товара?', 'Привязать материал к актуальному продукту, составу и инструкции.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: БАДы и товары для здоровья', 'review', 1, 'remaining-health-question-1'),
  ('ki-r-health-q2', 'question_to_client', 'creator', 'claims', 'Разрешённые свойства товара для здоровья', 'Какие свойства и формулировки подтверждены документами и кто со стороны бренда проверит рекламный материал?', NULL, NULL, 'Есть ли слова о лечении, профилактике или гарантированном эффекте, которые нельзя использовать?', 'Составить список разрешённых утверждений до подготовки контента.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: БАДы и товары для здоровья', 'review', 1, 'remaining-health-question-2'),
  ('ki-r-health-ob1', 'objection_response', 'creator', 'claims', 'Ответ: «Напишем, что продукт лечит»', 'Напишем, что продукт лечит', 'Нельзя приписывать товару лечебное действие без законного и документального основания. Формулировка должна соответствовать официальному статусу, маркировке и подтверждённым свойствам продукта.', 'Эмоциональную подачу можно строить вокруг сценария использования и проверяемых характеристик, а не медицинского обещания.', 'Какая точная формулировка подтверждена документами?', 'Передать текст ответственному специалисту клиента и удалить неподтверждённые обещания.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: БАДы и товары для здоровья', 'review', 1, 'remaining-health-objection-1'),
  ('ki-r-health-ob2', 'objection_response', 'creator', 'trust', 'Ответ: «Добавим рекомендацию врача, которой не было»', 'Добавим рекомендацию врача, которой не было', 'Нельзя создавать вымышленную рекомендацию специалиста, отзыв или знак одобрения. Экспертное мнение используется только при реальном участии человека, проверке текста и согласованных правах.', 'Авторитет нельзя имитировать с помощью AI-персонажа или неподтверждённой цитаты.', 'Есть ли реальный специалист и письменное разрешение на использование рекомендации?', 'Получить подтверждение либо заменить формат объяснением состава и инструкции.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: БАДы и товары для здоровья', 'review', 1, 'remaining-health-objection-2'),
  ('ki-r-health-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: БАДы и товары для здоровья', NULL, 'Не обещать лечение, не скрывать ограничения, не выдумывать экспертные рекомендации и не искажать упаковку или состав.', 'Тексты сверяются с актуальной маркировкой и документами. Отдельно проверяются предупреждения, способ применения и граница между товаром и медицинской помощью.', 'Понимает ли покупатель реальный статус продукта и ограничения его применения?', 'Остановить публикацию до подтверждения формулировок ответственным специалистом.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: БАДы и товары для здоровья', 'review', 1, 'remaining-health-ethics-1'),

  ('ki-r-experts-q1', 'question_to_client', 'creator', 'business', 'Компетенция и продукт эксперта', 'В чём подтверждённая компетенция эксперта, какой продукт предлагается и кому он действительно подходит?', NULL, NULL, 'Какой конкретный результат получает клиент и что зависит от его собственных действий?', 'Сформулировать продукт без завышения статуса и обещаний.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: Эксперты и специалисты', 'review', 1, 'remaining-experts-question-1'),
  ('ki-r-experts-q2', 'question_to_client', 'creator', 'evidence', 'Подтверждение опыта и кейсов эксперта', 'Какие образование, опыт, сертификаты, кейсы и результаты можно подтвердить и использовать публично?', NULL, NULL, 'Есть ли разрешения клиентов на публикацию историй и цифр?', 'Собрать доказательства и отделить личное мнение от профессионального факта.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Эксперты и специалисты', 'review', 1, 'remaining-experts-question-2'),
  ('ki-r-experts-ob1', 'objection_response', 'creator', 'trust', 'Ответ: «Добавим награды и клиентов для солидности»', 'Добавим награды и клиентов для солидности', 'Нельзя приписывать эксперту несуществующие награды, должности, публикации или проекты. Сильную позицию можно построить на реальной специализации, процессе и проверяемых результатах.', 'Недостаток громких регалий не оправдывает создание ложного авторитета.', 'Какие реальные факты лучше всего подтверждают компетенцию?', 'Выбрать 3–5 проверяемых доказательств и раскрыть их контекст.', 'any', 'firm', 'required', 'refusal', 'manual', NULL, 'Массовое наполнение: Эксперты и специалисты', 'review', 1, 'remaining-experts-objection-1'),
  ('ki-r-experts-ob2', 'objection_response', 'creator', 'guarantees', 'Ответ: «Пообещаем клиенту гарантированный доход»', 'Пообещаем клиенту гарантированный доход', 'Доход зависит от исходной ситуации, действий клиента, рынка и множества внешних факторов. Корректно описывать метод, поддержку и подтверждённые кейсы, но не обещать индивидуальный финансовый результат.', 'Обещание результата заменяется прозрачными условиями работы и критериями полезности.', 'Что эксперт контролирует лично, а что остаётся ответственностью клиента?', 'Согласовать честную формулировку результата и ограничений.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Эксперты и специалисты', 'review', 1, 'remaining-experts-objection-2'),
  ('ki-r-experts-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: Эксперты и специалисты', NULL, 'Не выдумывать квалификацию, кейсы, отзывы и гарантии. Сохранять конфиденциальность клиентов и указывать границы компетенции.', 'Результаты раскрываются с контекстом и разрешением. Эксперт не выдаёт мнение за медицинскую, юридическую или финансовую гарантию вне своей компетенции.', 'Можно ли подтвердить каждое существенное утверждение и право на использование истории клиента?', 'Удалить неподтверждённый авторитет или заменить его прозрачным описанием опыта.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: Эксперты и специалисты', 'review', 1, 'remaining-experts-ethics-1'),

  ('ki-r-b2b-q1', 'question_to_client', 'creator', 'business', 'B2B-продукт и лицо, принимающее решение', 'Что компания поставляет, кому, какую бизнес-задачу решает и кто участвует в выборе поставщика?', NULL, NULL, 'Как выглядит путь от первого интереса до договора или пилота?', 'Зафиксировать продукт, отрасль, роли в закупке и следующий коммерческий шаг.', 'any', 'neutral', 'required', 'normal', 'manual', NULL, 'Массовое наполнение: B2B-компании и поставщики', 'review', 1, 'remaining-b2b-question-1'),
  ('ki-r-b2b-q2', 'question_to_client', 'creator', 'evidence', 'Спецификации, мощности и подтверждения B2B', 'Какие характеристики, объёмы, сроки, сертификаты, география и условия поставки подтверждены и актуальны?', NULL, NULL, 'Какие сведения являются конфиденциальными или зависят от индивидуального расчёта?', 'Подготовить проверяемый перечень фактов и границы публичного раскрытия.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: B2B-компании и поставщики', 'review', 1, 'remaining-b2b-question-2'),
  ('ki-r-b2b-ob1', 'objection_response', 'creator', 'accuracy', 'Ответ: «Покажем производство и мощности крупнее»', 'Покажем производство и мощности крупнее', 'Нельзя выдавать сгенерированный цех, оборудование или объём выпуска за реальные мощности компании. Концептуальная сцена допустима только с ясным обозначением и не должна подтверждать несуществующую способность выполнить заказ.', 'Для доверия лучше показать реальные процессы, документы и измеримые возможности.', 'Какие мощности можно подтвердить фотографиями, данными и действующими документами?', 'Собрать фактические материалы и убрать неподтверждённые масштабы.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: B2B-компании и поставщики', 'review', 1, 'remaining-b2b-objection-1'),
  ('ki-r-b2b-ob2', 'objection_response', 'creator', 'guarantees', 'Ответ: «Контент гарантирует контракт или победу в тендере»', 'Контент гарантирует контракт или победу в тендере', 'Материалы помогают объяснить компетенции и упростить оценку поставщика, но решение зависит от требований, цены, документов, конкурентов и закупочной процедуры. Гарантия контракта некорректна.', 'Можно отвечать за ясность и точность предложения, но не за решение другой организации.', 'Какие критерии выбора известны и какие из них подтверждает контент?', 'Собрать доказательства по критериям и согласовать реалистичный следующий шаг.', 'any', 'firm', 'recommended', 'elevated', 'manual', NULL, 'Массовое наполнение: B2B-компании и поставщики', 'review', 1, 'remaining-b2b-objection-2'),
  ('ki-r-b2b-eth1', 'ethical_rule', 'system', 'ethics', 'Обязательная проверка: B2B-компании', NULL, 'Точно указывать характеристики, мощности, сертификаты, клиентов и результаты; не раскрывать закрытые данные и условия договоров.', 'Логотипы клиентов, объекты и показатели используются только при наличии права на публикацию. Индивидуальные условия не выдаются за универсальные.', 'Подтверждены ли факты и разрешено ли раскрывать каждого названного клиента или объект?', 'Удалить неподтверждённые данные или обезличить материал.', 'any', 'firm', 'required', 'high', 'manual', NULL, 'Массовое наполнение: B2B-компании и поставщики', 'review', 1, 'remaining-b2b-ethics-1')
)
INSERT OR IGNORE INTO knowledge_items (
  id, item_type, speaker, category, title, prompt_text, short_text, full_text,
  clarification_text, next_action_text, channel, tone, required_level, risk_level,
  source_kind, source_url, source_reference, status, version, normalized_key,
  created_at, updated_at
)
SELECT
  id, item_type, speaker, category, title, prompt_text, short_text, full_text,
  clarification_text, next_action_text, channel, tone, required_level, risk_level,
  source_kind, source_url, source_reference, status, version, normalized_key,
  CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM seed;

WITH niche_map (source_slug, niche_id) AS (
  VALUES
  ('children', 'niche-children'),
  ('tourism', 'niche-tourism'),
  ('interior', 'niche-interior'),
  ('realestate', 'niche-real-estate'),
  ('womenspaces', 'niche-women-spaces'),
  ('education', 'niche-education'),
  ('medical', 'niche-medical'),
  ('health', 'niche-health-products'),
  ('experts', 'niche-experts'),
  ('b2b', 'niche-b2b')
)
INSERT OR IGNORE INTO knowledge_item_niches (knowledge_item_id, niche_id, relevance)
SELECT ki.id, nm.niche_id, 'primary'
FROM knowledge_items ki
JOIN niche_map nm ON ki.id LIKE 'ki-r-' || nm.source_slug || '-%';

INSERT OR IGNORE INTO knowledge_item_stages (knowledge_item_id, stage_id)
SELECT id, 'stage-full-diagnostic'
FROM knowledge_items
WHERE id LIKE 'ki-r-%-q%';

INSERT OR IGNORE INTO knowledge_item_stages (knowledge_item_id, stage_id)
SELECT id, 'stage-objections'
FROM knowledge_items
WHERE id LIKE 'ki-r-%-ob%';

INSERT OR IGNORE INTO knowledge_item_stages (knowledge_item_id, stage_id)
SELECT id, 'stage-audit'
FROM knowledge_items
WHERE id LIKE 'ki-r-%-eth%';
